// Encrypted backup of a Key Vault container (all secrets as stored, i.e. still sealed for protected containers).
// The backup password is generated by the app, shown once and never stored: whoever holds file + password can read
// every entry. File format (JSON):
//   { format: 'keevault-backup', v: 1, vault, created, createdBy, count, protected,
//     kdf: { name: 'PBKDF2-SHA256', iterations, salt }, data: AES-256-GCM(JSON of secrets) }
// The header is authenticated (AAD), so it cannot be altered without the password check failing.

import { b64uEncode, b64uDecode, utf8, fromUtf8 } from './util.js';
import { passwordKey, seal, unseal, PBKDF2_ITERATIONS } from './protect.js';
import { t } from './i18n.js';

export const BACKUP_FORMAT = 'keevault-backup';
export const BACKUP_EXTENSION = 'kvbackup';
const ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // no I/O/0/1 – printed and typed by hand

export class BackupPasswordError extends Error {
  constructor() {
    super(t('Das Backup-Passwort ist falsch oder die Datei wurde verändert'));
    this.name = 'BackupPasswordError';
  }
}

/** 30 random characters in 6 groups (150 bits), e.g. ABCDE-FGHJK-… */
export function generateBackupPassword() {
  const bytes = crypto.getRandomValues(new Uint8Array(30));
  const chars = [...bytes].map((b) => ALPHABET[b & 31]);
  return chars.join('').match(/.{5}/g).join('-');
}

export const normalizeBackupPassword = (text) => String(text || '').toUpperCase().replace(/[^A-Z0-9]/g, '');

const headerAad = (h) => `${BACKUP_FORMAT}|${h.v}|${h.vault}|${h.created}|${h.count}|${h.protected}|${h.kdf.salt}|${h.kdf.iterations}`;

/** secrets: [{ name, value, contentType, tags }] → file content (string). */
export async function createBackup({ vault, secrets, password, createdBy = '', isProtected = false, iterations = PBKDF2_ITERATIONS }) {
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const header = {
    format: BACKUP_FORMAT, v: 1, vault, created: new Date().toISOString(), createdBy, count: secrets.length,
    protected: Boolean(isProtected), kdf: { name: 'PBKDF2-SHA256', iterations, salt: b64uEncode(salt) },
  };
  const key = await passwordKey(normalizeBackupPassword(password), salt, iterations);
  const payload = utf8(JSON.stringify(secrets.map(({ name, value, contentType, tags }) => ({ name, value, contentType: contentType || '', tags: tags || {} }))));
  const data = await seal(key, payload, headerAad(header));
  return JSON.stringify({ ...header, data: typeof data === 'string' ? data : b64uEncode(data) }, null, 1);
}

/** Header without the password (to show what the file contains). */
export function readBackupHeader(text) {
  let doc;
  try {
    doc = JSON.parse(text);
  } catch {
    doc = null;
  }
  if (doc?.format !== BACKUP_FORMAT || !doc.data || !doc.kdf?.salt) throw new Error(t('Die Datei ist kein Keevault-Backup'));
  if (doc.v > 1) throw new Error(t('Das Backup stammt aus einer neueren Version von Keevault'));
  const { data, ...header } = doc;
  return header;
}

/** → { header, secrets } */
export async function openBackup(text, password) {
  const header = readBackupHeader(text);
  const doc = JSON.parse(text);
  const key = await passwordKey(normalizeBackupPassword(password), b64uDecode(header.kdf.salt), header.kdf.iterations);
  let plain;
  try {
    plain = await unseal(key, doc.data, headerAad(header));
  } catch {
    throw new BackupPasswordError();
  }
  const secrets = JSON.parse(fromUtf8(plain instanceof Uint8Array ? plain : new Uint8Array(plain)));
  return { header, secrets };
}
